  `clasessType` varchar(40) CHARACTER SET utf8mb3 COLLATE utf8mb3_persian_ci DEFAULT NULL,
  `clasessCreatetime` timestamp NULL DEFAULT NULL,
  `clasessLastupdate` timestamp NULL DEFAULT NULL,
  `clasessStatus` int NOT NULL DEFAULT '1',
